  "headline": "FDA's shortage list shows Curium US LLC and Sun Pharmaceutical Industries, Inc. on allocation since 2023-12-27; no public FDA signal at our plants",
  "headline_cites": ["E5", "E6", "E7"],
  "sentences": [
    {
      "text": "FDA's shortage list shows Curium US LLC and Sun Pharmaceutical Industries, Inc. have been on allocation for technetium tc 99m pyrophosphate since 2023-12-27.",
      "cites": ["E5", "E6", "E7"]
    },
    {
      "text": "As of 2026-10-21 the shortage has been on FDA's list for 34 months.",
      "cites": ["D6"]
    },
    {
      "text": "A Class II recall by Curium US, LLC for lack of assurance of sterility and improper crimps on vials started 2024-11-26, 335 days after FDA posted the shortage.",
      "cites": ["D2", "E4"]
    },
    {
      "text": "The product label names Curium US LLC plants in Maryland Heights as the manufacturer.",
      "cites": ["E2", "E3"]
    },
    {
      "text": "There is no public FDA signal at our plants for this drug.",
      "cites": []
    },
    {
      "text": "The best option by rule is to buy from Cardinal Health 414, LLC, which is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D3"]
    }
  ]
}
